from h import *
L=[]
L.append(R(3066,"Pir Rebus","Siap mengubah pir biasa menjadi makanan penutup lezat? Ahli gizi ginjal DaVita, Geri dari Washington, akan menunjukkan cara membuat makanan lezat untuk diet ginjal dengan resep ramah ginjalnya, Pir Rebus.","4","1/2 pir",
["1 sendok teh kayu manis","2 sendok teh gula","2 buah pir ’Anjou","4 sendok teh mentega","2 cangkir jus cranberry"],
["Campurkan kayu manis dan gula dalam mangkuk kecil.","Belah pir menjadi dua dan dengan sendok keluarkan biji dan tangkainya.","Buat irisan tipis melintang pada bagian bulat pir, agar pir dapat rebah rata dalam loyang.","Letakkan pir dengan sisi kulit menghadap ke bawah dalam loyang dan taburi bagian atas dengan campuran kayu manis dan gula.","Letakkan 1 sendok teh mentega pada lubang biji setiap pir.","Tuang jus di dasar loyang.","Tutup dengan foil dan panggang pada suhu 350° F sekitar 30 menit atau hingga pir lunak saat ditusuk dengan garpu."],
["Jika loyang Anda dangkal, Anda mungkin memerlukan lebih sedikit jus. Jus hanya perlu naik setengah dari sisi pir.","Tuang jus di atas pir sebelum disajikan jika diinginkan.","Bagi penderita diabetes, gunakan jus cranberry rendah kalori dan pengganti gula sebagai ganti gula."],["2 buah, rendah kalium","1 lemak"]))
L.append(R(3067,"Tortilla Asparagus Kembang Kol","Cindy, ahli gizi ginjal DaVita dari Wisconsin, berfokus pada keinginan diet ginjal individual pasiennya dan berusaha mewujudkannya. Resep diet dialisis yang lezat seperti Tortilla Asparagus Kembang Kol yang enak dan mengenyangkan ini mudah dibuat dan akan memuaskan rasa lapar Anda, menyenangkan lidah Anda, dan membantu mewujudkan impian hasil laboratorium yang sehat.","4","1/4 tortilla",
["2 cangkir asparagus, dipotong seukuran gigitan","2 cangkir kembang kol, dipotong seukuran gigitan","2 sendok teh minyak zaitun","1-1/2 cangkir bawang bombai, dicincang halus","1 siung bawang putih, dicincang halus","1 cangkir pengganti telur cair rendah kolesterol","2 sendok makan peterseli segar, dicincang halus","1/4 sendok teh garam","1/2 sendok teh lada yang baru digiling","1/4 sendok teh daun thyme kering, dihancurkan","1/4 sendok teh pala bubuk"],
["Letakkan potongan asparagus dan kembang kol ditambah 1 sendok makan air dalam wadah tertutup yang aman untuk microwave. Microwave selama 3 hingga 5 menit untuk mengukus hingga empuk tetapi masih renyah.","Tumis bawang bombai hingga keemasan, sekitar 7 menit.","Tambahkan bawang putih dan masak sambil diaduk, 1 menit lagi.","Aduk asparagus, kembang kol, pengganti telur, peterseli, garam, lada, thyme, dan pala.","Kecilkan api dan masak tertutup hingga set dan kecokelatan di bagian bawah, sekitar 10 hingga 15 menit.","Longgarkan tepinya dengan pisau dan balikkan ke piring saji hangat atau sajikan langsung dari wajan."],
["Di Spanyol dan Amerika Selatan, tortilla adalah omelet bundar yang tidak dilipat, biasanya dibuat dengan telur, sayuran, dan bumbu. Sebagai perbandingan, tortilla Meksiko adalah roti pipih tipis yang terbuat dari tepung terigu atau jagung giling."],["1 daging","2 sayuran, kalium sedang"]))
L.append(R(3068,"Kembang Kol Panggang dengan Rosemary","Kembang kol bisa dengan mudah menjadi sayuran rendah kalium favorit Anda setelah mencicipi Kembang Kol Panggang dengan Rosemary. Diciptakan oleh tim ahli gizi DaVita, sayuran panggang ini dibumbui ringan dengan minyak, sedikit garam, lada, dan rosemary segar. Kembang Kol Panggang dengan Rosemary mudah dibuat dan ramah ginjal.","9","2/3 cangkir",
["6 cangkir kuntum kembang kol","1 sendok makan rosemary segar","1-1/2 sendok makan minyak zaitun","1/4 sendok teh garam","1/4 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 450° F.","Potong kuntum kembang kol menjadi potongan seukuran gigitan. Cincang rosemary.","Dalam mangkuk besar, aduk kembang kol dengan bahan-bahan lainnya.","Sebarkan kembang kol yang sudah dibumbui di atas loyang yang tidak diolesi lemak.","Panggang selama 15 menit; angkat dari oven dan aduk.","Lanjutkan memanggang selama 10 menit atau hingga kembang kol empuk dan kecokelatan ringan."],
["Berhati-hatilah saat mengeluarkan loyang dari oven untuk mengaduk kembang kol."],["1 sayuran, kalium sedang","1/2 lemak"]))
L.append(R(3069,"Sayuran dan Pasta ala Italia dengan Ayam","Cobalah resep ramah ginjal Sayuran dan Pasta ala Italia dengan Ayam untuk makan malam besar Anda berikutnya.","2","1-1/4 cangkir",
["1 sendok makan minyak zaitun","1/2 cangkir paprika hijau","1/4 cangkir bawang bombai","1/2 sendok teh bawang putih bubuk","1/2 cangkir kuntum brokoli segar","1 sendok teh rosemary kering","1 sendok makan kemangi segar","1/4 sendok teh serpihan cabai merah","1/8 sendok teh garam","2 ons daging ayam, matang","1/4 cangkir kaldu ayam rendah natrium","2 sendok teh tepung maizena","1 cangkir pasta spiral, matang"],
["Cincang paprika dan bawang bombai. Potong dadu ayam.","Masukkan minyak ke dalam wajan antilengket besar dan tumis paprika, bawang bombai, dan brokoli. Taburi dengan rosemary, kemangi, serpihan cabai merah, bawang putih bubuk, dan garam.","Aduk ayam yang sudah matang.","Campurkan kaldu ayam dengan tepung maizena dan tambahkan ke campuran sayuran dan ayam. Masak hingga sedikit mengental. Aduk 1 cangkir pasta matang yang masih panas.","Angkat dari api dan sajikan."],
["Ayam dapat ditingkatkan menjadi 6 ons bagi penderita yang menjalani dialisis. Kandungan protein akan meningkat menjadi 29 gram per porsi.","Untuk persiapan cepat, gunakan 1-1/4 cangkir campuran sayuran beku dengan komposisi serupa untuk menggantikan sayuran segar.","Tambahkan serpihan cabai merah lebih banyak atau lebih sedikit sesuai toleransi Anda terhadap makanan pedas.","Peras jus lemon atau percikkan cuka balsamik untuk menambah rasa segar asam."],["1 daging","1 karbohidrat","1 sayuran, kalium sedang","1 lemak"]))
L.append(R(3077,"Makan Malam Paket Foil Daging Giling dan Sayuran","Mudah dirakit dan mudah dibersihkan adalah gambaran sempurna untuk resep ahli gizi DaVita, Grace, Makan Malam Paket Foil Daging Giling dan Sayuran. Selain itu, Anda dapat memvariasikan jenis protein dan sayuran untuk menjadikan resep ini hidangan makan malam ramah ginjal yang praktis.","1","3 ons daging sapi, 3/4 cangkir sayuran",
["4 ons daging sapi giling","1/4 cangkir bawang bombai","1 sendok makan saus Worcestershire","3/4 cangkir wortel dan kacang polong beku","1/4 sendok teh campuran kering dressing Italia","1/4 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 375° F. Semprot selembar foil dengan semprotan masak antilengket. Cincang bawang bombai.","Campurkan daging sapi giling, bawang bombai, dan saus Worcestershire menjadi satu patty dan letakkan di atas foil.","Letakkan kacang polong dan wortel beku di atas patty.","Taburkan campuran dressing Italia dan lada hitam di atasnya.","Lipat dan rapatkan foil lalu letakkan di atas loyang. Panggang selama 35 menit.","Buka salah satu ujung bungkusan foil dengan hati-hati dan biarkan uap keluar sebelum disajikan."],
["Semprot foil dengan semprotan masak.","Letakkan bungkusan foil di atas loyang sebelum dimasukkan ke dalam oven."],["3 daging","1/2 karbohidrat","1-1/2 sayuran, kalium sedang"]))
L.append(R(3078,"Kopi Hazelnut Kayu Manis","Awali hari dengan nada yang lezat bersama resep ramah ginjal Kopi Hazelnut Kayu Manis.","4","8 ons (1 cangkir)",
["4 cangkir kopi seduh","8 sendok teh Torani® Sugar Free Classic Hazelnut Syrup","4 sendok makan susu rendah lemak 1%","4 batang kayu manis"],
["Seduh kopi dengan mesin pembuat kopi. Tuang ke dalam cangkir kecil.","Tambahkan 2 sendok teh Torani® Sugar Free Classic Hazelnut Syrup dan 1 sendok makan susu (atau krimer) ke setiap cangkir dan hiasi masing-masing dengan sebatang kayu manis."],
["Cobalah berbagai rasa sirup Torani® Sugar Free.","Jika Anda lebih suka kopi yang lebih pekat, tidak usah menambahkan susu.","Banyak krimer nonsusu mengandung zat tambahan fosfat. Waspadai hal ini jika Anda mengganti sirup dengan krimer hazelnut nonsusu."],["tidak ada"]))
L.append(R(3079,"Kue Cinnamon Roll","Bahan Persiapan Tips Bermanfaat","24","persegi 2\" x 2\"",
["1-1/2 cangkir mentega","3-1/8 cangkir tepung terigu serbaguna","1/4 sendok teh garam","2 cangkir Splenda® baking blend","1-1/2 sendok teh soda kue","3 sendok teh cream of tartar","1-1/2 cangkir + 5 sendok makan susu beras, tanpa fortifikasi","2 butir telur","3 sendok teh vanila","1 cangkir Splenda® brown sugar blend","1 sendok makan kayu manis","1 cangkir gula halus"],
["Panaskan oven terlebih dahulu hingga 350° F.","Lelehkan 1/2 cangkir mentega dan biarkan sisa mentega di luar agar lunak.","Dalam mangkuk berukuran sedang, campurkan 3 cangkir tepung, garam, 1 cangkir Splenda baking blend, soda kue, cream of tartar, 1-1/2 cangkir Rice Dream, telur, dan 2 sendok teh vanila. Aduk perlahan mentega yang sudah dilelehkan.","Tuang campuran ke dalam loyang 9″ x 13″ yang sudah diolesi lemak.","Campurkan 1 cangkir mentega yang sudah lunak, Splenda brown sugar blend, 2 sendok makan tepung, dan kayu manis hingga tercampur rata. Jatuhkan secara merata di atas adonan dan putar-putar dengan pisau.","Panggang selama 28-32 menit.","Campurkan sisa 1 cangkir Splenda baking blend dan gula halus, 5 sendok makan susu beras, dan 1 sendok teh vanila. Siramkan di atas kue selagi masih hangat."],
["Makanan penutup tinggi kalori ini sangat baik untuk menambah kalori. Nikmati untuk sarapan atau makanan penutup.","Jika tersedia, 1 cangkir pengganti gula halus Ideal® dapat digunakan untuk menggantikan 1 cangkir Splenda baking blend dan 1 cangkir gula halus guna mengurangi kalori dan karbohidrat."],["1 karbohidrat","2 tinggi kalori","2 lemak"]))
L.append(R(3080,"Meatloaf Kalkun","Resep ramah ginjal Meatloaf Kalkun dari Sara menampilkan sedikit sosis kalkun pedas, memberikan sensasi yang tidak Anda duga tetapi pasti Anda nikmati. Meatloaf Kalkun mungkin tampak familier, tetapi akan memperkenalkan Anda pada cita rasa yang sama sekali baru.","6","3 ons",
["1 pon daging kalkun giling, 7% lemak","3 ons sosis kalkun","1 butir telur utuh","1 putih telur","1/2 cangkir remah roti kering","1/4 cangkir peterseli segar, dicincang","1 sendok makan saus Worcestershire","1 sendok teh bumbu dan saus pewarna cokelat Gravy Master®","1 sendok teh bumbu Italia","1/2 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 350° F.","Campurkan semua bahan dalam mangkuk besar dan aduk rata.","Pindahkan ke loyang roti 9″ x 5″ yang sudah diolesi lemak dan panggang selama 1 jam.","Iris menjadi 6 potong yang sama besar dan sajikan."],
["Pilih merek sosis dengan natrium terendah.","Gunakan sosis kalkun pedas untuk rasa yang lebih kuat."],["3 daging","1/2 karbohidrat"]))
L.append(R(3082,"Minuman Penyegar Delima","Jus delima, jus lemon, dan soda klub dipadukan untuk menciptakan Minuman Penyegar Delima yang meriah dan bersoda ini.","1","6 ons (3/4 cangkir)",
["1/4 cangkir jus delima","1 sendok makan jus lemon","1/2 cangkir soda klub","1 sendok makan biji delima (arils)","irisan lemon untuk hiasan"],
["Masukkan jus delima dan jus lemon ke dalam gelas kecil.","Tambahkan soda klub di atasnya.","Tambahkan biji delima dan hiasi dengan lemon."],
["Jus delima dibatasi hingga 1/4 cangkir dalam resep ini. Satu cangkir jus delima mengandung lebih dari 500 mg kalium.","Ganti jus delima dengan jus cranberry jika lebih suka. Kalium berkurang menjadi 46 mg.","Tambahkan sedikit pemanis favorit Anda untuk rasa manis tambahan."],["1 buah, kalium sedang"]))
L.append(R(3083,"Semur Domba atau Kambing dengan Pangsit","Jika Anda belum pernah mencobanya, atau jarang menyajikannya, ahli gizi ginjal DaVita, Miriam dari Arizona, memiliki resep Semur Domba atau Kambing dengan Pangsit yang lezat, ramah ginjal, dan merupakan hidangan satu panci yang memasak semuanya dalam satu panci.","7","1-1/4 cangkir",
["6 cangkir air","1 pon daging domba untuk semur","1 cangkir bawang bombai, dicincang kasar","2 cangkir zucchini","3 ons cabai hijau, kalengan","2 cangkir tepung terigu serbaguna putih","1/2 sendok teh garam","2 sendok teh baking powder","1 sendok teh gula"],
["Ukur air dan masukkan ke dalam panci semur.","Buang lemak dari daging dan potong menjadi potongan seukuran gigitan. Masukkan daging dan tulang ke dalam air. Letakkan di atas kompor dengan api sedang.","Cincang kasar bawang bombai. Belah dua zucchini memanjang dan iris setebal 1/2”","Masukkan bawang bombai, zucchini, dan cabai ke dalam semur.","Setelah semur mendidih perlahan, kecilkan api dan biarkan mendidih perlahan setidaknya 1 jam.","Selagi semur dimasak, campurkan tepung, garam, baking powder, dan gula dalam mangkuk.","Uleni air hangat ke dalam bahan kering untuk membentuk bola adonan yang lembut.","Tutup adonan dan biarkan istirahat selama 20 hingga 30 menit.","Setelah semur dimasak selama 1 jam, bentuk bola adonan sekitar 2-1/2” menjadi bundar pipih. (Tidak perlu sempurna atau rata).","Sobek adonan seukuran koin dan jatuhkan ke dalam semur.","Terus bentuk bola adonan 2-1/2” menjadi bundar pipih dan sobek adonan seukuran koin lalu jatuhkan ke dalam semur hingga semua adonan masuk ke dalam semur.","Masak pangsit dalam semur selama 20 menit lagi.","Sajikan dan nikmati."],
["Panggang 2-3 cabai Hatch sebagai pengganti cabai kalengan."],["2 daging","1 sayuran, kalium sedang","1-1/2 karbohidrat"]))
L.append(R(3084,"Ayam Shake and Bake Istimewa","Kesabaran bukan hanya kebajikan, tetapi juga bakat. Sama seperti memasak, mengembangkan kepedulian adalah keterampilan yang dapat disempurnakan, seperti yang telah ditunjukkan Mary, ahli gizi ginjal DaVita dari Minnesota. Mary telah mengasah keterampilannya dalam “sabar terhadap pasien,” serta kreativitasnya dalam menciptakan resep lezat, seperti Ayam Shake and Bake Istimewa yang ramah ginjal.","6","1 potong ayam (3 ons tanpa tulang)",
["1-1/2 cangkir remah roti kering halus","1 cangkir tepung terigu serbaguna putih","4 sendok makan peterseli kering","1 sendok makan paprika","2 sendok teh bawang bombai bubuk","1-1/2 sendok teh bawang putih bubuk","1 sendok teh lada hitam","1 sendok makan marjoram","1 sendok makan thyme","3 sendok makan minyak sayur","2 pon potongan ayam, dengan tulang"],
["Panaskan oven terlebih dahulu hingga 375° F.","Olesi loyang dengan minyak sayur (dapat menggunakan kertas roti atau alas silpat) dan sisihkan.","Campurkan remah roti, tepung, peterseli, paprika, bawang bombai bubuk, bawang putih bubuk, lada hitam, marjoram, dan thyme. Aduk hingga tercampur rata.","Tambahkan minyak ke campuran remah roti dan aduk dengan garpu hingga tercampur sempurna.","Simpan dalam wadah kedap udara di tempat sejuk dan kering atau simpan di freezer.","Untuk menyiapkan ayam: Bilas ayam dengan air dan biarkan potongan ayam tetap lembap dengan air sambil mengibaskan kelebihan cairan.","Tuang 1 cangkir campuran remah roti ke dalam kantong penyimpan makanan plastik yang bersih. Masukkan 1 hingga 2 potong ayam sekaligus ke dalam kantong dan kocok hingga terlapisi merata.","Letakkan di atas loyang yang sudah diolesi lemak dan panggang selama 40 hingga 45 menit. Balik sekali, setelah 20 menit."],
["Resep ini menghasilkan campuran pelapis yang cukup untuk 3 kali makan. Simpan sisa campuran dalam wadah tertutup atau kantong freezer dan bekukan hingga siap digunakan lagi.","Untuk membuat remah roti kering buatan sendiri, panggang roti berumur sehari hingga renyah tetapi tidak gosong. Hancurkan dalam blender atau food processor."],["3 daging","1 karbohidrat"]))
L.append(R(3085,"Kubis Brussel, Wortel, dan Apel Panggang","Tingkatkan cita rasa sayuran musim gugur dengan memanggangnya dan menambahkan sedikit sirup maple. Kubis Brussel, Wortel, dan Apel Panggang adalah resep ramah ginjal, mudah untuk makan malam apa pun dan cukup istimewa untuk disajikan pada makan malam spesial.","8","1/2 cangkir",
["20 kubis Brussel ukuran sedang","3 wortel besar","2 apel ukuran sedang","1/4 cangkir minyak zaitun","2 sendok makan sirup maple","1 sendok teh kayu manis","1/2 sendok teh pala","1/4 sendok teh garam"],
["Panaskan oven terlebih dahulu hingga 375° F. Semprot loyang dengan semprotan masak antilengket.","Pangkas kubis Brussel dan belah dua masing-masing. Kupas wortel dan potong menjadi potongan 1 inci. Buang bagian inti apel dan potong dadu 1/2 inci.","Masukkan kubis Brussel, wortel, dan potongan apel ke dalam mangkuk besar.","Dalam mangkuk kecil campurkan minyak zaitun, sirup maple, dan rempah. Aduk hingga tercampur.","Tuang saus ke dalam mangkuk besar dan aduk hingga sayuran dan apel terlapisi. Letakkan bahan-bahan di atas loyang. Taburi dengan 1/4 sendok teh garam.","Panggang selama 30 hingga 40 menit hingga wortel empuk saat ditusuk garpu dan kubis Brussel mulai menggelap."],
["Ganti wortel dengan 2 lobak ukuran sedang jika diinginkan.","Tambahkan sisa makanan ke dalam campuran sayuran salad untuk salad sayuran panggang yang mengenyangkan keesokan harinya."],["1-1/2 sayuran, kalium sedang","1/2 buah, rendah kalium","1 lemak"]))
L.append(R(3090,"Boulette Udang","Boulette Udang adalah kesenangan bagi pencinta makanan laut karena kepiting atau lobster air tawar dapat dengan mudah menggantikan udang. Diciptakan oleh pasien DaVita, Ken di Louisiana, Boulette Udang memberikan sentuhan ramah ginjal pada hidangan favorit Cajun tempo dulu.","10","3 boulette",
["2 pon udang mentah","2 cangkir bawang bombai","1 paprika hijau","1 ikat peterseli","4 butir telur besar","2 sendok teh bawang putih bubuk","2 sendok teh bumbu Cajun tanpa garam","1/2 cangkir hingga 1 cangkir tepung terigu serbaguna putih","1 kuart minyak untuk menggoreng"],
["Cincang halus udang, bawang bombai, paprika, dan peterseli. Kocok telur.","Campurkan semua bahan kecuali tepung dalam mangkuk pengaduk.","Setelah dicampur, tambahkan tepung secara bertahap. Terus tambahkan tepung sedikit demi sedikit hingga campuran menjadi kental dan menempel pada sendok.","Untuk menggoreng, panaskan minyak dalam wajan besar atau penggorengan dalam. Jatuhkan satu sendok adonan udang berukuran sedang ke dalam minyak panas dan masak hingga cokelat dan renyah di kedua sisi.","Angkat dari minyak dan tiriskan di atas tisu dapur. Sajikan hangat."],
["Bumbu Cajun yang disarankan antara lain Bumbu Cajun Tanpa Garam buatan sendiri di DaVita.com, campuran bumbu Cajun Mrs. Dash, atau bumbu Cajun Tanpa Garam Benoit’s Best. Hindari produk dengan kalium klorida.","Alih-alih menggoreng, Anda dapat membentuk adonan menjadi patty dan memanggangnya di atas loyang yang sudah diolesi lemak pada suhu 350° F hingga cokelat keemasan.","Cobalah kepiting atau lobster air tawar sebagai pengganti udang. Keduanya sama-sama enak!"],["3 daging","1 karbohidrat","1/2 sayuran, kalium sedang","1 lemak"]))
L.append(R(3091,"Napoleon Beri","Manjakan selera manis Anda dalam diet ginjal dengan Napoleon Beri, makanan penutup sederhana dan lezat dari ahli gizi ginjal Marie dari Colorado. Dinikmati sendiri atau dipadukan dengan hidangan elegan, makanan penutup rendah kalium ini sempurna untuk diet ginjal.","6","satu tumpukan wonton berisi",
["12 kulit wonton","2 sendok makan gula pasir","1 cangkir whipped topping bebas lemak Reddi-Wip®","1/2 cangkir raspberry","1/2 cangkir blueberry","1 sendok makan gula halus"],
["Panaskan oven terlebih dahulu hingga 400° F.","Semprotkan semprotan masak pada loyang yang muat untuk 12 kulit wonton.","Bentangkan kulit wonton, dan semprot dengan semprotan masak.","Taburkan gula pasir pada kulit wonton.","Panggang wonton selama 5 menit atau hingga cokelat keemasan; angkat dari loyang.","Letakkan 6 kulit wonton di nampan saji.","Taruh di atas setiap kulit 2 sendok makan whipped topping, 1 sendok makan raspberry, dan 1 sendok makan blueberry.","Tutup buah beri dengan kulit wonton kedua.","Taburi bagian atasnya dengan gula halus. Hiasi dengan sedikit whipped topping, buah, dan daun mint, jika diinginkan. Sajikan segera."],
["Ganti raspberry dan blueberry dengan stroberi dan blackberry untuk variasi.","Untuk mengurangi kandungan karbohidrat, ganti gula dengan pemanis granular Splenda® No Calorie.","Jika wonton disimpan di lemari es, Reddi-Wip akan meleleh. Rakit hanya saat siap disajikan."],["1/2 karbohidrat","1/2 tinggi kalori"]))
L.append(R(3092,"Poppy Krunch","Mencari camilan cepat yang ringan, renyah, dan manis? Ahli gizi ginjal DaVita, Jackie dari North Carolina, punya jawabannya: Poppy Krunch. Anak-anak akan menyukai camilan dari popcorn yang disiram topping manis berbutter ini, tetapi orang dewasa pun pasti ingin mendapat bagiannya. Dan karena ramah ginjal, mereka yang memiliki masalah ginjal dapat menikmatinya tanpa","12","1 cangkir",
["12 cangkir popcorn, sudah dimasak, tanpa garam","1-1/3 cangkir gula","1/2 cangkir sirup jagung berwarna terang","1 cangkir mentega","1 sendok teh ekstrak vanila"],
["Sebarkan popcorn dalam loyang dangkal.","Campurkan gula, sirup jagung, dan mentega dalam panci 1/2 liter.","Masak dengan api sedang hingga sedikit campuran yang dijatuhkan ke dalam air dingin terpisah menjadi benang tipis yang keras tetapi tidak rapuh (280° F pada termometer permen). Angkat dari api.","Tambahkan vanila.","Tuang sirup ke atas popcorn, aduk hingga terlapisi rata. Sebarkan di atas loyang yang sudah diolesi lemak. Patahkan menjadi potongan-potongan.","Biarkan dingin. Simpan dalam wadah kedap udara hingga siap disajikan."],
["Bagi menjadi porsi individual dan simpan untuk camilan atau makanan penutup cepat sepanjang minggu."],["1 karbohidrat","1 tinggi kalori"]))
save(5,L)
